{"action":"write_file","path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>Alpine Snow Globe</title>
<style>
  :root{--ink:#13233a;--ice:#dceeff;--blue:#75b7e8;--gold:#e8bc70}
  *{box-sizing:border-box} body{margin:0;min-height:100vh;overflow:hidden;background:#08152b;color:#f7fbff;font-family:ui-rounded,"Avenir Next",Avenir,system-ui,sans-serif}
  .sky{position:fixed;inset:0;background:radial-gradient(circle at 75% 18%,#315b94 0 2%,transparent 13%),radial-gradient(ellipse at 50% 110%,#315e91 0,transparent 57%),linear-gradient(180deg,#08152b 0%,#163967 54%,#527fa8 100%)}
  .stars,.stars:before,.stars:after{position:absolute;inset:0;content:"";background-image:radial-gradient(white 1px,transparent 1.8px);background-size:73px 93px;opacity:.5}.stars:before{transform:translate(31px,45px);background-size:117px 113px;opacity:.32}.stars:after{transform:translate(-19px,21px);background-size:149px 157px;opacity:.22}
  main{position:relative;z-index:1;min-height:100vh;display:grid;place-items:center;padding:26px}
  .title{position:fixed;top:35px;left:42px;letter-spacing:.22em;text-transform:uppercase;font-size:11px;color:#c2dcf3;font-weight:700}.title strong{display:block;color:white;font-size:25px;letter-spacing:-.035em;text-transform:none;margin-top:8px;font-weight:650}
  .hint{position:fixed;bottom:33px;left:42px;color:#d1e5f7;font-size:13px;display:flex;align-items:center;gap:10px}.gesture{border:1px solid #9ec4e255;border-radius:99px;padding:5px 10px;color:#f9fdff}
  .globe-wrap{width:min(76vw,650px);aspect-ratio:1/1.2;position:relative;display:flex;align-items:flex-start;justify-content:center;filter:drop-shadow(0 32px 32px #00102799);user-select:none;touch-action:none;cursor:grab}.globe-wrap.dragging{cursor:grabbing}
  .glass{position:absolute;top:0;width:100%;aspect-ratio:1;border-radius:50%;overflow:hidden;border:2px solid #dff5ff88;background:radial-gradient(circle at 33% 25%,#effcff48 0 2%,transparent 12%),linear-gradient(145deg,#bdecff36,#6bb4ef12 49%,#d5f4ff32);box-shadow:inset 16px 10px 30px #fff4,inset -17px -12px 30px #1e70aa88,0 0 0 7px #d8f5ff17;transform:perspective(900px) rotateX(var(--tilt,0deg))}
  .world{position:absolute;inset:8% 4% 2%;transform-style:preserve-3d;transform:rotateY(var(--rotate,0deg));transition:transform .1s linear}
  .snowground{position:absolute;bottom:1%;left:0;width:100%;height:35%;border-radius:50% 50% 0 0;background:radial-gradient(ellipse at 50% 15%,#fff 0 30%,#cce8f5 58%,#7ab1d3 100%);box-shadow:0 -10px 20px #fff8}
  .peak{position:absolute;left:20%;bottom:20%;width:61%;height:58%;clip-path:polygon(50% 0,100% 100%,0 100%);background:linear-gradient(100deg,#537e9b 0 47%,#23475f 48% 100%);filter:drop-shadow(0 10px 8px #102d4755)}
  .peak:before{content:"";position:absolute;inset:0;clip-path:polygon(50% 0,76% 44%,58% 34%,48% 55%,30% 38%);background:#f8ffff}.peak:after{content:"";position:absolute;inset:0;background:linear-gradient(130deg,transparent 45%,#8ab2ca 46% 50%,transparent 51%);opacity:.7}
  .backpeak{position:absolute;bottom:27%;left:1%;width:47%;height:40%;clip-path:polygon(50% 0,100% 100%,0 100%);background:#729db6;opacity:.8}.backpeak:after{content:"";position:absolute;inset:0;clip-path:polygon(50% 0,75% 48%,51% 37%,29% 51%);background:#f5feff}
  .trees{position:absolute;bottom:16%;left:7%;width:86%;height:43%;display:flex;align-items:flex-end;justify-content:space-between;transform:translateZ(15px)}.tree{width:10%;height:72%;position:relative;background:linear-gradient(90deg,#6b4935 45%,#b7895d 46% 55%,#543626 56%);border-radius:3px 3px 0 0}.tree:before,.tree:after{content:"";position:absolute;left:50%;transform:translateX(-50%);width:260%;clip-path:polygon(50% 0,100% 100%,0 100%);background:linear-gradient(90deg,#164b4e,#327a73 57%,#0c3a41)}.tree:before{height:68%;top:-50%}.tree:after{height:62%;top:-15%}.tree:nth-child(2){height:58%;opacity:.85}.tree:nth-child(3){height:92%}.tree:nth-child(4){height:52%;opacity:.78}.tree:nth-child(5){height:75%}
  .snow{position:absolute;inset:0;pointer-events:none}.flake{position:absolute;width:var(--s);height:var(--s);left:var(--x);top:var(--y);background:white;border-radius:50%;opacity:var(--o);box-shadow:0 0 5px white;animation:drift var(--d) linear infinite;animation-delay:var(--delay)}@keyframes drift{to{transform:translate3d(var(--dx),230px,0);opacity:.05}}
  .shine{position:absolute;inset:0;border-radius:50%;pointer-events:none;background:radial-gradient(ellipse at 30% 20%,#fff8 0 3%,#fff2 11%,transparent 28%),linear-gradient(120deg,#fff4 0 2%,transparent 17% 82%,#fff3 96%);mix-blend-mode:screen}
  .base{position:absolute;bottom:0;width:72%;height:20%;border-radius:46% 46% 11% 11%/32% 32% 14% 14%;background:linear-gradient(180deg,#d8b56e,#9a6439 34%,#5b2f25 100%);box-shadow:inset 0 7px 8px #ffe9a780,inset 0 -12px 13px #280e1988,0 18px 18px #00102399}.base:before{content:"ALPINE WINTER";position:absolute;inset:29% 9% auto;height:31%;border-top:1px solid #ffe8a488;border-bottom:1px solid #ffe8a466;text-align:center;padding-top:9px;color:#fff1bc;font-size:10px;letter-spacing:.23em;text-shadow:0 1px #5b281c}
  button{position:fixed;right:38px;bottom:33px;border:1px solid #dff1ff88;background:#eaf6ff18;color:white;border-radius:99px;padding:12px 18px;font:600 13px inherit;letter-spacing:.04em;backdrop-filter:blur(10px);cursor:pointer;transition:.2s}button:hover{background:#eaf6ff33;transform:translateY(-2px)}.shake .glass{animation:wobble .65s ease-in-out}.shake .flake{animation-duration:1.2s!important}@keyframes wobble{0%,100%{transform:rotate(0)}20%{transform:rotate(-3deg)}45%{transform:rotate(3deg)}70%{transform:rotate(-2deg)}}
  @media(max-width:600px){.title{top:23px;left:24px}.hint{left:24px;bottom:23px;font-size:11px}.globe-wrap{width:94vw}.title strong{font-size:21px}button{right:20px;bottom:68px}}
</style>
</head><body><div class="sky"><div class="stars"></div></div><main><div class="title">Snow globe collection<strong>Alpine Midnight</strong></div><div class="globe-wrap" id="globe"><div class="glass"><div class="world"><div class="backpeak"></div><div class="peak"></div><div class="snowground"></div><div class="trees"><i class="tree"></i><i class="tree"></i><i class="tree"></i><i class="tree"></i><i class="tree"></i></div></div><div class="snow" id="snow"></div><div class="shine"></div></div><div class="base"></div></div><div class="hint"><span class="gesture">drag</span> rotate the scene</div><button id="shake">Shake the snow</button></main>
<script>
const globe=document.getElementById('globe'),snow=document.getElementById('snow'),button=document.getElementById('shake');
for(let i=0;i<78;i++){const f=document.createElement('i');f.className='flake';const s=(Math.random()*4+1).toFixed(1);f.style.cssText=`--s:${s}px;--x:${Math.random()*100}%;--y:${Math.random()*105-15}%;--o:${.3+Math.random()*.7};--d:${5+Math.random()*7}s;--delay:${-Math.random()*10}s;--dx:${(Math.random()-.5)*70}px`;snow.appendChild(f)}
let angle=-8,startX,startAngle,down=false;function set(){globe.style.setProperty('--rotate',angle+'deg')}set();
globe.addEventListener('pointerdown',e=>{down=true;startX=e.clientX;startAngle=angle;globe.classList.add('dragging');globe.setPointerCapture(e.pointerId)});globe.addEventListener('pointermove',e=>{if(!down)return;angle=startAngle+(e.clientX-startX)*.55;set()});globe.addEventListener('pointerup',()=>{down=false;globe.classList.remove('dragging')});
button.onclick=()=>{globe.classList.remove('shake');void globe.offsetWidth;globe.classList.add('shake');setTimeout(()=>globe.classList.remove('shake'),800)};
</script></body></html>"}
